signature.code:
function useField(path: string): FieldState & {
  onChange: (value) => void;
  onBlur: () => void;
  reset: () => void;
}

examples.code:
function EmailField() {
  const { value, error, onChange, onBlur } = useField("email");
  return (
    <input
      value={value ?? ""}
      onChange={(e) => onChange(e.target.value)}
      onBlur={onBlur}
      aria-invalid={!!error}
    />
  );
}
